/// Cumulative structural-work capacity for independent Core validation.
///
/// Validation reauthenticates the complete admitted Core program, including
/// fixed Kind structure. Construction, rebuilding, and every other type-work
/// owner retain [`TYPE_WORK_LIMIT`].
const CORE_VALIDATION_TYPE_WORK_LIMIT: usize = 3 * TYPE_WORK_LIMIT;

#[inline]
fn core_validation_type_work_limit() -> usize {
    crate::calibration::limit(
        CORE_VALIDATION_TYPE_WORK_LIMIT,
        crate::calibration::DiagnosticOwner::Core,
    )
}

fn same_provider_family_application(
    actual: &InterfaceApplication,
    expected: &InterfaceApplication,
    work: &mut TypeWorkBudget,
) -> Result<bool, ()> {
    work.charge(1)?;
    if actual.interface() != expected.interface()
        || actual.arguments().len() != expected.arguments().len()
    {
        return Ok(false);
    }
    for (actual, expected) in actual.arguments().iter().zip(expected.arguments()) {
        if !crate::types::same_kinded_argument_with_budget(actual, expected, work)? {
            return Ok(false);
        }
    }
    Ok(true)
}

/// Checks the exact source-native operation table, then legacy registrations.
/// Pay before the lookup and each legacy inventory traversal.
pub(crate) fn registered_foreign_effect_with_charge<E>(
    registry: &crate::resolved::ResolvedRegistry,
    effect: crate::types::EffectId,
    mut charge: impl FnMut(usize) -> Result<(), E>,
) -> Result<bool, E> {
    charge(1)?;
    if registry
        .native_symbol(OperationId::new(effect, 0))
        .is_some()
    {
        return Ok(true);
    }
    for module in registry.foreign_modules() {
        charge(1)?;
        charge(module.effects.len())?;
        if module.effects.contains(&effect) {
            return Ok(true);
        }
    }
    Ok(false)
}

/// Returns the borrowed canonical state fact only after paying for every
/// visited module and its complete state inventory.
pub(crate) fn registered_foreign_state_with_charge<E>(
    registry: &crate::resolved::ResolvedRegistry,
    state: crate::types::NominalTypeId,
    mut charge: impl FnMut(usize) -> Result<(), E>,
) -> Result<Option<&crate::foreign::ForeignStateFact>, E> {
    for module in registry.foreign_modules() {
        charge(1)?;
        charge(module.states.len())?;
        if let Some(state) = module.states.iter().find(|fact| fact.id == state) {
            return Ok(Some(state));
        }
    }
    Ok(None)
}

struct TypeReplacementMap(HashMap<crate::types::TypeVariableId, Type>);

impl TypeReplacementMap {
    fn new() -> Self {
        Self(HashMap::new())
    }

    fn try_reserve(&mut self, additional: usize) -> Result<(), std::collections::TryReserveError> {
        self.0.try_reserve(additional)
    }

    fn insert_replacing(&mut self, parameter: crate::types::TypeVariableId, ty: Type) {
        if let Some(displaced) = self.0.insert(parameter, ty) {
            discard_type_iteratively(displaced);
        }
    }

    fn as_map(&self) -> &HashMap<crate::types::TypeVariableId, Type> {
        &self.0
    }
}

impl Drop for TypeReplacementMap {
    fn drop(&mut self) {
        for (_, ty) in self.0.drain() {
            discard_type_iteratively(ty);
        }
    }
}

#[derive(Debug)]
enum RegistrySourceOrder<'a, T> {
    Borrowed(std::slice::Iter<'a, T>),
    Contextual(std::vec::IntoIter<&'a T>),
}

impl<'a, T> Iterator for RegistrySourceOrder<'a, T> {
    type Item = &'a T;
    fn next(&mut self) -> Option<Self::Item> {
        match self {
            Self::Borrowed(rows) => rows.next(),
            Self::Contextual(rows) => rows.next(),
        }
    }
}

// Complete contextual keys determine natural nondecreasing runs. Merging
// adjacent runs preserves source-order ties and keeps all retained storage,
// comparisons and merge transfers in the caller's cumulative ledger.
fn registry_source_order<T>(
    rows: &[T],
    reorder: bool,
    mut key: impl FnMut(&T) -> Result<(ModuleId, u32), ValidationError>,
    mut charge: impl FnMut(usize) -> Result<(), ValidationError>,
) -> Result<RegistrySourceOrder<'_, T>, ValidationError> {
    if !reorder {
        return Ok(RegistrySourceOrder::Borrowed(rows.iter()));
    }
    let resource = || ValidationError::new(ValidationReason::Resource, None);
    charge(rows.len())?;
    let mut keys = Vec::new();
    keys.try_reserve_exact(rows.len()).map_err(|_| resource())?;
    for row in rows {
        keys.push(key(row)?);
    }
    if rows.is_empty() {
        return Ok(RegistrySourceOrder::Borrowed(rows.iter()));
    }

    // Every key must complete before classifying even the first run.
    // There can be at most one run start per row.
    charge(rows.len())?;
    let mut runs = Vec::new();
    runs.try_reserve_exact(rows.len()).map_err(|_| resource())?;
    runs.push(0usize);
    for (index, pair) in keys.windows(2).enumerate() {
        charge(1)?;
        if pair[0] > pair[1] {
            runs.push(index.checked_add(1).ok_or_else(resource)?);
        }
    }
    if runs.len() == 1 {
        return Ok(RegistrySourceOrder::Borrowed(rows.iter()));
    }

    charge(rows.len())?;
    let mut order = Vec::new();
    order
        .try_reserve_exact(rows.len())
        .map_err(|_| resource())?;
    order.extend(0..rows.len());
    charge(rows.len())?;
    let mut scratch = Vec::new();
    scratch
        .try_reserve_exact(rows.len())
        .map_err(|_| resource())?;
    scratch.extend_from_slice(&order);
    while runs.len() > 1 {
        charge(1)?;
        let run_count = runs.len();
        let mut input = 0usize;
        let mut output = 0usize;
        while input < run_count {
            // Three boundary reads and one in-place compacted start.
            charge(4)?;
            let next = input.checked_add(1).ok_or_else(resource)?;
            let following = input.checked_add(2).ok_or_else(resource)?;
            let start = runs[input];
            let middle = runs.get(next).copied().unwrap_or(rows.len());
            let end = runs.get(following).copied().unwrap_or(rows.len());
            runs[output] = start;
            let (mut left, mut right) = (start, middle);
            for target in &mut scratch[start..end] {
                charge(1)?;
                let take_left = if left == middle {
                    false
                } else if right == end {
                    true
                } else {
                    charge(1)?;
                    keys[order[left]] <= keys[order[right]]
                };
                *target = if take_left {
                    let value = order[left];
                    left += 1;
                    value
                } else {
                    let value = order[right];
                    right += 1;
                    value
                };
            }
            output = output.checked_add(1).ok_or_else(resource)?;
            input = following;
        }
        runs.truncate(output);
        std::mem::swap(&mut order, &mut scratch);
    }
    charge(rows.len())?;
    let mut result = Vec::new();
    result
        .try_reserve_exact(rows.len())
        .map_err(|_| resource())?;
    result.extend(order.into_iter().map(|index| &rows[index]));
    Ok(RegistrySourceOrder::Contextual(result.into_iter()))
}

struct CorePatternMatrix(Vec<Vec<CorePattern>>);

impl Drop for CorePatternMatrix {
    fn drop(&mut self) {
        for row in self.0.drain(..) {
            for pattern in row {
                pattern.discard_iteratively();
            }
        }
    }
}

struct CorePatternRow(Vec<CorePattern>);

impl CorePatternRow {
    fn into_inner(mut self) -> Vec<CorePattern> {
        std::mem::take(&mut self.0)
    }
}

impl Drop for CorePatternRow {
    fn drop(&mut self) {
        for pattern in self.0.drain(..) {
            pattern.discard_iteratively();
        }
    }
}

struct OwnedTypeSequence(std::vec::IntoIter<Type>);

impl OwnedTypeSequence {
    fn next(&mut self) -> Option<Type> {
        self.0.next()
    }
}

type CoreTypeBinders<'a> = HashMap<crate::types::TypeVariableId, (&'a Kind, NodeId)>;
type CoreAbstractionOwners = HashMap<NodeId, BinderId>;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RegistryParameterOwner {
    Nominal(crate::types::NominalTypeId),
    Effect(crate::types::EffectId),
    ProviderDeclaration(crate::resolved::ResourceDefinitionId),
}

type RegistryParameterOwners = HashMap<crate::types::TypeVariableId, RegistryParameterOwner>;

#[derive(Clone, Copy)]
enum MonotypeVariableKinds<'scope, 'kind> {
    Core(&'scope CoreTypeBinders<'kind>),
    CatalogOwner(&'scope [(crate::types::TypeVariableId, Kind)]),
    Registry {
        owner: crate::types::NominalTypeId,
        parameter_owners: &'scope RegistryParameterOwners,
    },
}

enum OwnerValidationRoot<'a> {
    Type(&'a Type),
    Argument(&'a crate::types::KindedArgument),
    Instance(&'a EffectInstance),
    Row(&'a EffectRow),
    TypeRows(&'a Type),
}

#[derive(Clone, Copy)]
enum OwnerValidationRole {
    KindOnly,
    FinalRows(NodeId),
}

enum OwnerValidationOutput {
    Kind(Option<Kind>),
    Validated,
}

impl Drop for OwnedTypeSequence {
    fn drop(&mut self) {
        for ty in self.0.by_ref() {
            discard_type_iteratively(ty);
        }
    }
}

/// The independently checked invariant that malformed Core violated.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ValidationReason {
    /// A variable or binder identity violates lexical scope.
    Scope,
    /// A node or binder has an inconsistent structural type.
    NodeType,
    /// An application disagrees with its function domain or codomain.
    ApplicationType,
    /// A recursive binding violates its group-shape invariants.
    RecursiveBinding,
    /// Required causal source provenance is missing or invalid.
    Provenance,
    /// A stored node does not belong to the selected pure dialect.
    DialectMembership,
    /// A node refers outside its arena.
    NodeBounds,
    /// The expression graph contains a cycle.
    Cycle,
    /// The selected root does not belong to the arena.
    Root,
    /// The arena contains a node unreachable from its selected root.
    Unreachable,
    /// The immutable nominal and constructor registry is malformed.
    Registry,
    /// A typed structured pattern is malformed.
    Pattern,
    /// Match arms are redundant or non-exhaustive.
    Coverage,
    /// A deterministic validation resource budget was exhausted.
    Resource,
    /// An explicit Core type abstraction or application is malformed.
    TypeOperation,
    /// A Core type variable occurs outside its abstraction scope.
    TypeScope,
    /// A module-newtype conversion does not match its canonical representation relation.
    NewtypeConversion,
    /// A retained effect or operation does not authenticate against its registry.
    EffectIdentity,
    /// A retained computation row or effect-row equation is false.
    EffectRow,
    /// A retained handler does not cover or discharge its exact instance.
    Handler,
    /// A retained resume violates ownership, use, or non-escape.
    Resume,
    /// Discard has no authenticated proof of capture safety.
    DiscardUnsafe,
    /// A stored value crosses the boundary of its resource owner.
    ResourceEscape,
}

impl fmt::Display for ValidationReason {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(match self {
            Self::Scope => "core.validation.scope",
            Self::NodeType => "core.validation.node-type",
            Self::ApplicationType => "core.validation.application-type",
            Self::RecursiveBinding => "core.validation.recursive-binding",
            Self::Provenance => "core.validation.provenance",
            Self::DialectMembership => "core.validation.dialect-membership",
            Self::NodeBounds => "core.validation.node-bounds",
            Self::Cycle => "core.validation.cycle",
            Self::Root => "core.validation.root",
            Self::Unreachable => "core.validation.unreachable",
            Self::Registry => "core.validation.registry",
            Self::Pattern => "core.validation.pattern",
            Self::Coverage => "core.validation.coverage",
            Self::Resource => "core.validation.resource",
            Self::TypeOperation => "core.validation.type-operation",
            Self::TypeScope => "core.validation.type-scope",
            Self::NewtypeConversion => "core.validation.newtype-conversion",
            Self::EffectIdentity => "core.validation.effect-identity",
            Self::EffectRow => "core.validation.effect-row",
            Self::Handler => "core.validation.handler",
            Self::Resume => "core.validation.resume",
            Self::DiscardUnsafe => "core.validation.discard-unsafe",
            Self::ResourceEscape => "core.validation.resource-escape",
        })
    }
}

