    #[derive(Clone, Copy, Debug)]
    enum VectorApplicationMutation {
        Missing,
        Extra,
        Reordered,
        WrongKind,
        WrongArgumentIdentity,
        WrongInterface,
    }

    fn mutate_vector_application_for_test(
        application: &mut InterfaceApplication,
        mutation: VectorApplicationMutation,
    ) -> bool {
        let mut interface = application.interface();
        let mut arguments = application.arguments().to_vec();
        match mutation {
            VectorApplicationMutation::Missing => {
                if arguments.len() < 2 {
                    return false;
                }
                arguments.pop();
            }
            VectorApplicationMutation::Extra => {
                arguments.push(crate::types::KindedArgument::TypeArg(Type::Unit))
            }
            VectorApplicationMutation::Reordered => {
                if arguments.len() < 2 {
                    return false;
                }
                arguments.swap(0, 1);
            }
            VectorApplicationMutation::WrongKind => {
                let Some(first) = arguments.first_mut() else {
                    return false;
                };
                crate::types::discard_kinded_argument_iteratively(std::mem::replace(
                    first,
                    crate::types::KindedArgument::TypeArg(Type::Forall(
                        Box::new([]),
                        Box::new(Type::Unit),
                    )),
                ));
            }
            VectorApplicationMutation::WrongArgumentIdentity => {
                let Some(first) = arguments.first_mut() else {
                    return false;
                };
                crate::types::discard_kinded_argument_iteratively(std::mem::replace(
                    first,
                    crate::types::KindedArgument::TypeArg(Type::Variable(
                        crate::types::TypeVariableId::generated(u32::MAX),
                    )),
                ));
            }
            VectorApplicationMutation::WrongInterface => {
                interface = crate::interface::InterfaceId::new(ModuleId::new(u32::MAX - 1), 0);
            }
        }
        *application = InterfaceApplication::new_kinded(interface, arguments.into_boxed_slice());
        true
    }

    #[derive(Clone, Copy, Debug)]
    enum VectorApplicationTarget {
        ImplementationOwner,
        Domain,
        Occurrence,
        AdapterEdge,
        Anchor,
    }

    #[test]
    fn independent_core_rejects_every_complete_application_vector_tamper() {
        let fixture = vector_method_evidence_validation_fixture();
        let LinkedCoreValidationFixture {
            directory,
            graph,
            program,
            module_sources,
            globals: _,
        } = fixture;
        let sources = graph
            .modules()
            .iter()
            .map(|module| module.source())
            .collect::<Vec<_>>();
        let validated = validate_modules(program, &sources, &module_sources)
            .expect("the complete-vector fixture should validate before tampering");

        for target in [
            VectorApplicationTarget::ImplementationOwner,
            VectorApplicationTarget::Domain,
            VectorApplicationTarget::Occurrence,
            VectorApplicationTarget::AdapterEdge,
            VectorApplicationTarget::Anchor,
        ] {
            for mutation in [
                VectorApplicationMutation::Missing,
                VectorApplicationMutation::Extra,
                VectorApplicationMutation::Reordered,
                VectorApplicationMutation::WrongKind,
                VectorApplicationMutation::WrongArgumentIdentity,
                VectorApplicationMutation::WrongInterface,
            ] {
                let mut tampered = identity_traversal(&validated)
                    .expect("the validated vector fixture should rebuild independently");
                let changed = match target {
                    VectorApplicationTarget::ImplementationOwner => {
                        let catalog = Arc::make_mut(&mut tampered.method_evidence);
                        catalog
                            .implementation_owners_mut_for_core_test()
                            .iter_mut()
                            .find(|row| row.application.arguments().len() == 2)
                            .is_some_and(|row| {
                                mutate_vector_application_for_test(&mut row.application, mutation)
                            })
                    }
                    VectorApplicationTarget::Domain => {
                        let catalog = Arc::make_mut(&mut tampered.method_evidence);
                        catalog
                            .domains_mut_for_core_test()
                            .iter_mut()
                            .find(|row| row.application.arguments().len() == 2)
                            .is_some_and(|row| {
                                mutate_vector_application_for_test(&mut row.application, mutation)
                            })
                    }
                    VectorApplicationTarget::Occurrence => {
                        let catalog = Arc::make_mut(&mut tampered.method_evidence);
                        catalog
                            .occurrences_mut_for_core_test()
                            .iter_mut()
                            .find(|row| row.checked_application.arguments().len() == 2)
                            .is_some_and(|row| {
                                mutate_vector_application_for_test(
                                    &mut row.checked_application,
                                    mutation,
                                )
                            })
                    }
                    VectorApplicationTarget::AdapterEdge => {
                        let catalog = Arc::make_mut(&mut tampered.method_evidence);
                        catalog
                            .adapters_mut_for_core_test()
                            .iter_mut()
                            .flat_map(|adapter| &mut adapter.prerequisites)
                            .find(|edge| edge.application.arguments().len() == 2)
                            .is_some_and(|edge| {
                                mutate_vector_application_for_test(&mut edge.application, mutation)
                            })
                    }
                    VectorApplicationTarget::Anchor => tampered
                        .method_evidence_anchors
                        .iter_mut()
                        .find(|anchor| anchor.application.arguments().len() == 2)
                        .is_some_and(|anchor| {
                            mutate_vector_application_for_test(&mut anchor.application, mutation)
                        }),
                };
                assert!(
                    changed,
                    "the {target:?} fixture must expose a width-two carrier"
                );
                assert!(
                    validate_modules(tampered, &sources, &module_sources).is_err(),
                    "independent Core accepted {target:?} {mutation:?}",
                );
            }
        }
        drop(directory);
    }

    #[test]
    fn independent_core_rejects_interface_parameter_vector_tampering() {
        #[derive(Clone, Copy, Debug)]
        enum Mutation {
            Missing,
            Extra,
            Reordered,
            WrongIdentity,
        }

        let fixture = vector_method_evidence_validation_fixture();
        let LinkedCoreValidationFixture {
            directory,
            graph,
            program,
            module_sources,
            globals: _,
        } = fixture;
        let sources = graph
            .modules()
            .iter()
            .map(|module| module.source())
            .collect::<Vec<_>>();
        let validated = validate_modules(program, &sources, &module_sources)
            .expect("the complete-vector fixture should validate before parameter tampering");

        for mutation in [
            Mutation::Missing,
            Mutation::Extra,
            Mutation::Reordered,
            Mutation::WrongIdentity,
        ] {
            let mut tampered = identity_traversal(&validated)
                .expect("the validated vector fixture should rebuild independently");
            let catalog = Arc::make_mut(&mut tampered.method_evidence);
            let method = catalog
                .methods_mut_for_core_test()
                .iter_mut()
                .find(|method| method.interface_parameters.len() == 2)
                .expect("the fixture retains a width-two method parameter row");
            let mut parameters = method.interface_parameters.to_vec();
            match mutation {
                Mutation::Missing => {
                    parameters.pop();
                }
                Mutation::Extra => {
                    parameters.push(crate::types::TypeVariableId::generated(u32::MAX));
                }
                Mutation::Reordered => parameters.swap(0, 1),
                Mutation::WrongIdentity => {
                    parameters[0] = crate::types::TypeVariableId::generated(u32::MAX);
                }
            }
            method.interface_parameters = parameters.into_boxed_slice();
            assert!(
                validate_modules(tampered, &sources, &module_sources).is_err(),
                "independent Core accepted {mutation:?} interface parameters",
            );
        }
        drop(directory);
    }

    fn replace_recursive_initializer_for_method_evidence_test(
        program: &mut UnvalidatedProgram,
        binder: BinderId,
        initializer: NodeId,
    ) -> Option<NodeId> {
        for node in &mut program.nodes {
            let PureExprKind::Computation(PureComputation::RecursiveBind(group)) = &mut node.kind
            else {
                continue;
            };
            if let Some(member) = group
                .members_mut()
                .iter_mut()
                .find(|member| member.binder().id() == binder)
            {
                return Some(member.replace_initializer_for_core_test(initializer));
            }
        }
        None
    }

    #[test]
    fn linked_method_evidence_rejects_wrong_owner_envelopes() {
        enum Case {
            UnanchoredWrapper,
            MovedToDifferentOwner,
            SharedByUnrelatedRecursiveBinder,
        }

        for case in [
            Case::UnanchoredWrapper,
            Case::MovedToDifferentOwner,
            Case::SharedByUnrelatedRecursiveBinder,
        ] {
            let mut fixture = method_evidence_validation_fixture();
            let owners = fixture
                .program
                .method_evidence_anchors
                .iter()
                .filter_map(|anchor| match anchor.role {
                    MethodEvidenceAnchorRole::ImplementationOwner { binder, .. } => {
                        Some((binder, anchor.node))
                    }
                    _ => None,
                })
                .collect::<Vec<_>>();
            match case {
                Case::UnanchoredWrapper => {
                    let domain = fixture
                        .program
                        .method_evidence_anchors
                        .iter()
                        .find(|anchor| {
                            matches!(anchor.role, MethodEvidenceAnchorRole::Domain { .. })
                                && matches!(anchor.owner, Some(MethodEvidenceOwner::Global(_)))
                        })
                        .expect("the fixture has a polymorphic global domain");
                    let Some(MethodEvidenceOwner::Global(binder)) = domain.owner else {
                        unreachable!()
                    };
                    let domain_node = domain.node;
                    let domain_type = fixture.program.nodes
                        [domain_node.index().expect("domain index")]
                    .ty
                    .clone();
                    let origin = fixture.program.nodes[domain_node.index().expect("domain index")]
                        .origin
                        .clone();
                    let fresh = crate::types::TypeVariableId::generated(u32::MAX);
                    let wrapper = NodeId::new(
                        fixture.program.arena,
                        u32::try_from(fixture.program.nodes.len()).expect("fixture size"),
                    );
                    fixture.program.nodes.push(StoredNode {
                        dialect: DialectId::PURE,
                        effects: (),
                        ty: Type::Forall(
                            vec![(fresh, Kind::Type)].into_boxed_slice(),
                            Box::new(domain_type),
                        ),
                        kind: PureExprKind::Computation(PureComputation::TypeAbstraction(
                            TypeAbstractionNode::new(vec![(fresh, Kind::Type)], domain_node),
                        )),
                        origin,
                    });
                    replace_recursive_initializer_for_method_evidence_test(
                        &mut fixture.program,
                        binder,
                        wrapper,
                    )
                    .expect("the global owner is recursively bound");
                }
                Case::MovedToDifferentOwner => {
                    let [(first_binder, _), (_, second_root), ..] = owners.as_slice() else {
                        panic!("the fixture has two implementation owners")
                    };
                    replace_recursive_initializer_for_method_evidence_test(
                        &mut fixture.program,
                        *first_binder,
                        *second_root,
                    )
                    .expect("the first implementation owner is recursively bound");
                }
                Case::SharedByUnrelatedRecursiveBinder => {
                    let &(owner_binder, owner_root) = owners
                        .first()
                        .expect("the fixture has an implementation owner");
                    let unrelated = fixture
                        .program
                        .nodes
                        .iter()
                        .find_map(|node| {
                            let PureExprKind::Computation(PureComputation::RecursiveBind(group)) =
                                &node.kind
                            else {
                                return None;
                            };
                            group
                                .members()
                                .iter()
                                .map(|member| member.binder().id())
                                .find(|binder| *binder != owner_binder)
                        })
                        .expect("the fixture has an unrelated recursive owner");
                    replace_recursive_initializer_for_method_evidence_test(
                        &mut fixture.program,
                        unrelated,
                        owner_root,
                    )
                    .expect("the unrelated owner is recursively bound");
                }
            }
            assert!(
                fixture.validate().is_err(),
                "an authenticated method domain must remain in its exact declared owner envelope",
            );
        }
    }

    #[test]
    fn unused_local_representation_still_requires_its_lexical_dependencies() {
        let fixture = LinkedCoreValidationFixture::compile(
            "",
            concat!(
                "main : Unit -> Int\nmain () = {\n",
                "    newtype Outer = Outer(Int)\n",
                "    newtype Inner = Inner(Outer)\n    42\n}\n",
            ),
            &[],
        );
        let sources = fixture
            .graph
            .modules()
            .iter()
            .map(|module| module.source())
            .collect::<Vec<_>>();
        let validated = validate_modules(fixture.program, &sources, &fixture.module_sources)
            .expect("unused nested nominals should validate");
        let mut tampered = identity_traversal(&validated).expect("scope traversal should rebuild");
        let scopes = tampered
            .nodes
            .iter()
            .enumerate()
            .filter_map(|(index, node)| match &node.kind {
                PureExprKind::Computation(PureComputation::LocalNominalScope(scope)) => {
                    Some((index, *scope))
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        let [(first_index, first), (second_index, second)] = scopes.as_slice() else {
            panic!("two local scopes expected")
        };
        tampered.nodes[*first_index].kind =
            PureExprKind::Computation(PureComputation::LocalNominalScope(
                crate::core::LocalNominalScopeNode::new(second.owner(), first.body()),
            ));
        tampered.nodes[*second_index].kind =
            PureExprKind::Computation(PureComputation::LocalNominalScope(
                crate::core::LocalNominalScopeNode::new(first.owner(), second.body()),
            ));
        assert_eq!(
            validate_modules(tampered, &sources, &fixture.module_sources)
                .expect_err("the representation dependency cannot precede its introduction")
                .reason(),
            ValidationReason::Scope
        );
        drop(fixture.directory);
    }

    const LEXICAL_AUTHENTICATION_SOURCE: &str = concat!(
        "interface Relation<A, B> where A -> B {\n",
        "read : A -> Int\nunused : A -> Int\nchoose<C, D> : (A, C, D) -> C\n}\n",
        "main : Unit -> Int\nmain () = {\n",
        "newtype N = N(Unit)\nnewtype M = M(Unit)\n",
        "with Relation<N, Bool> {\nread ignored = 20\nunused ignored = 0\n",
        "choose (ignored, value, extra) = value\n}\n",
        "with Relation<M, Int> {\nread ignored = 22\nunused ignored = 1\n",
        "choose (ignored, value, extra) = value\n}\n",
        "let marker = choose((N(()), true, ()))\nread(N(())) + read(M(()))\n}\n",
    );

    #[test]
    fn lexical_core_catalog_authenticates_unused_owners_and_contextual_parameters() {
        let fixture = LinkedCoreValidationFixture::compile("", LEXICAL_AUTHENTICATION_SOURCE, &[]);
        let sources = fixture
            .graph
            .modules()
            .iter()
            .map(|module| module.source())
            .collect::<Vec<_>>();
        let validated = validate_modules(fixture.program, &sources, &fixture.module_sources)
            .expect("the complete lexical catalog validates before mutation");
        let mut accepted_mutations = Vec::new();
        for mutation in [
            "source",
            "method",
            "binder",
            "dependent",
            "parameter-count",
            "parameter",
            "parameter-swap",
            "parameter-order",
        ] {
            let mut changed = identity_traversal(&validated).expect("independent Core copy");
            let mut owners = changed.method_evidence.lexical_owners().to_vec();
            assert_eq!(owners.len(), 6);
            let unused = owners
                .iter()
                .position(|owner| owner.method.declaration() == 1)
                .expect("an unused same-typed method");
            let source = owners[unused].source;
            let other_source = owners
                .iter()
                .find(|owner| owner.source != source)
                .expect("another real source")
                .source;
            match mutation {
                "source" => owners[unused].source = other_source,
                "method" => {
                    let read = owners
                        .iter()
                        .find(|owner| owner.source == source && owner.method.declaration() == 0)
                        .expect("same-typed read method")
                        .method;
                    owners[unused].method = read;
                }
                "binder" => {
                    let read = owners
                        .iter()
                        .find(|owner| owner.source == source && owner.method.declaration() == 0)
                        .expect("same-typed read binder")
                        .binder;
                    owners[unused].binder = read;
                }
                "dependent" => {
                    let owner = &mut owners[unused];
                    let dependent = if owner.application.arguments()[1]
                        == crate::types::KindedArgument::TypeArg(Type::Bool)
                    {
                        Type::Int
                    } else {
                        assert_eq!(
                            owner.application.arguments()[1],
                            crate::types::KindedArgument::TypeArg(Type::Int)
                        );
                        Type::Bool
                    };
                    owner.application = InterfaceApplication::new_kinded(
                        owner.application.interface(),
                        Box::new([
                            owner.application.arguments()[0].clone(),
                            crate::types::KindedArgument::TypeArg(dependent),
                        ]),
                    );
                }
                "parameter" | "parameter-count" | "parameter-swap" | "parameter-order" => {
                    let own = owners
                        .iter()
                        .position(|owner| {
                            owner.source == source && !owner.source_parameters.is_empty()
                        })
                        .expect("polymorphic supplied method");
                    if mutation == "parameter-order" {
                        assert_eq!(owners[own].source_parameters.len(), 2);
                        owners[own].source_parameters.swap(0, 1);
                    } else if mutation != "parameter-count" {
                        let other = owners
                            .iter()
                            .position(|owner| {
                                owner.source == other_source && !owner.source_parameters.is_empty()
                            })
                            .expect("independent same-kinded method parameter");
                        let original = owners[own].source_parameters[0];
                        assert_ne!(original, owners[other].source_parameters[0]);
                        owners[own].source_parameters[0] = owners[other].source_parameters[0];
                        if mutation == "parameter-swap" {
                            owners[other].source_parameters[0] = original;
                        }
                    } else {
                        owners[own].source_parameters = Box::new([]);
                    }
                }
                _ => unreachable!(),
            }
            Arc::make_mut(&mut changed.method_evidence).set_lexical_owners(owners);
            if validate_modules(changed, &sources, &fixture.module_sources).is_ok() {
                accepted_mutations.push(mutation);
            }
        }
        assert!(
            accepted_mutations.is_empty(),
            "accepted lexical catalog mutations: {accepted_mutations:?}"
        );
    }

    #[test]
    fn method_catalog_binary_lookup_bound_prepays_actual_key_comparisons() {
        use crate::interface::{ImplId, ImplMethodId, InterfaceId, MethodId};
        use crate::module::ModuleId;
        // These include empty/singleton catalogs, both sides of powers of two,
        // and a non-power-of-two catalog. Actual std comparisons are the witness.
        for (count, exact_work) in [
            (0, 3),
            (1, 4),
            (2, 5),
            (3, 6),
            (4, 6),
            (16, 8),
            (53, 10),
            (64, 10),
            (65, 11),
            (128, 11),
            (129, 12),
        ] {
            let keys = (0..count)
                .map(|index| {
                    let id = u32::try_from(index).unwrap();
                    let method =
                        MethodId::new(InterfaceId::new(ModuleId::new(id / 4), id % 4), id % 3);
                    ImplMethodId::new(ImplId::new(ModuleId::new(id / 4), id % 4), method)
                })
                .collect::<Vec<_>>();
            let missing_method = MethodId::new(InterfaceId::new(ModuleId::new(u32::MAX), 0), 0);
            let missing_impl =
                ImplMethodId::new(ImplId::new(ModuleId::new(u32::MAX), 0), missing_method);
            for key in keys
                .first()
                .copied()
                .into_iter()
                .chain(keys.last().copied())
                .chain([missing_impl])
            {
                let mut comparisons = 0;
                let _ = keys.binary_search_by(|probe| {
                    comparisons += 1;
                    probe.cmp(&key)
                });
                assert_eq!(comparisons + 3, exact_work);
                let mut method_comparisons = 0;
                let _ = keys.binary_search_by(|probe| {
                    method_comparisons += 1;
                    probe.method().cmp(&key.method())
                });
                assert_eq!(method_comparisons + 3, exact_work);
                let mut ordinal_comparisons = 0;
                let ordinals = (0..count).collect::<Vec<_>>();
                let _ = ordinals.binary_search_by(|probe| {
                    ordinal_comparisons += 1;
                    probe.cmp(&count)
                });
                assert_eq!(ordinal_comparisons + 3, exact_work);
            }

            let file = source();
            let arena = super::super::dialect::ArenaId::new(118);
            let program = UnvalidatedProgram {
                registry: Arc::new(crate::resolved::ResolvedRegistry::default()),
                method_evidence: Arc::new(super::super::dialect::MethodEvidenceCatalog::default()),
                method_evidence_anchors: Box::new([]),
                arena,
                nodes: vec![StoredNode {
                    dialect: DialectId::PURE,
                    effects: (),
                    ty: Type::Unit,
                    origin: Some(origin(&file)),
                    kind: PureExprKind::Value(PureValue::Unit(super::super::literal::UnitNode)),
                }],
                root: NodeId::new(arena, 0),
            };
            for remaining in 0..=exact_work {
                let validator = Validator::new(&program, &[&file]);
                validator
                    .charge_type_work(CORE_VALIDATION_TYPE_WORK_LIMIT - remaining)
                    .unwrap();
                let result = validator.charge_method_catalog_binary_lookup(count);
                if remaining < exact_work {
                    assert_eq!(result.unwrap_err().reason(), ValidationReason::Resource);
                } else {
                    result.unwrap();
                    assert_eq!(validator.type_work.get(), CORE_VALIDATION_TYPE_WORK_LIMIT);
                }
            }
        }
    }

    #[test]
    fn lexical_owner_parameter_authentication_has_an_exact_retry_boundary() {
        let fixture = LinkedCoreValidationFixture::compile("", LEXICAL_AUTHENTICATION_SOURCE, &[]);
        let sources = linked_fixture_sources(&fixture);
        let owner = fixture
            .program
            .method_evidence
            .lexical_owners()
            .iter()
            .find(|owner| owner.source_parameters.len() == 2)
            .expect("two contextual parameters");
        let anchor = fixture
            .program
            .method_evidence_anchors
            .iter()
            .find(|anchor| {
                matches!(anchor.role, MethodEvidenceAnchorRole::LexicalOwner { source, binder }
                if source == owner.source && binder == owner.binder)
            })
            .expect("owner anchor");
        // Three bound/access cells and three binary comparisons, two retained
        // identities, four spelling bytes and two kind cells authenticate the row.
        const EXACT: usize = 6 + 2 + 4 + 2;
        for remaining in [EXACT - 1, EXACT, EXACT] {
            let validator =
                Validator::new_modules(&fixture.program, &sources, &fixture.module_sources)
                    .expect("fixture relation");
            validator
                .charge_type_work(CORE_VALIDATION_TYPE_WORK_LIMIT - remaining)
                .unwrap();
            let result =
                validator.validate_lexical_owner_parameters(anchor, owner, &mut HashSet::new());
            if remaining < EXACT {
                assert_eq!(
                    result
                        .expect_err("parameter authentication charges before completion")
                        .reason(),
                    ValidationReason::Resource
                );
            } else {
                assert!(result.expect("exact parameter authentication"));
                assert_eq!(validator.type_work.get(), CORE_VALIDATION_TYPE_WORK_LIMIT);
            }
        }
    }

